        public static GeoBiome[] Biome(string key)
        {
            switch (key)
            {
                case "desert": return Desert;
                case "steppe": return Steppe;
                case "tropical": return Tropical;
                case "savanna": return Savanna;
                case "med": return Med;
                case "boreal": return Boreal;
                default: return null;
            }
        }

